-- The two checklists published on 2026-10-31: The First Month After a
-- Separation (Separation) and When a Parent Starts Needing Help
-- (Aging Parents).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-31`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-first-month-after-a-separation', 'The First Month After a Separation', 'For the first month after a separation, when everything needs deciding at once. It settles who tells whom, puts the money and the paperwork in set hours, keeps the children''s version of events the same from both sides, and lets a flat week be flat.', 'Separation', '["Decide who tells which people — a shared line spares you forty conversations.", "Separate the money before the feelings — one account, one list, one appointment.", "Write down what the children are told — the same words from both of you, every time.", "Pick one friend for the late nights — spreading it thin leaves everyone half-informed.", "Keep the house running on a short list — trash, bills, school forms, nothing else this month.", "Stop rereading the messages — rereading is not gathering evidence, it is bleeding.", "Put one hour a week on the paperwork — a set hour keeps it out of the other hundred.", "Let a flat week be the week it is — a month in is not late to still be reeling.", "Say nothing you would not want repeated — anything said this month may be quoted later."]'::jsonb, 'weekly', array['Relationships', 'Life Transitions']::text[], 1, '2026-10-31T16:00:00+00:00'::timestamptz),
  ('when-a-parent-starts-needing-help', 'When a Parent Starts Needing Help', 'For the point where a parent starts needing help and nobody has said so. It gets what you have noticed written down, asks them what they want first, walks the house for hazards, and divides the jobs with your siblings in writing.', 'Aging Parents', '["Write down what you have actually noticed — dates and examples travel better than worry.", "Ask them what they want before deciding — help done over someone''s head gets refused.", "Walk the house for the obvious hazards — the rug, the stairs, the water heater, the bath.", "Get the paperwork named while it is easy — who decides, who signs, where the documents live.", "Ask to be at the next appointment — two sets of ears and one written summary.", "Divide the jobs with your siblings in writing — whoever lives closest ends up with all of it.", "Find out what the county offers — rides, meals and day programs exist and go unused.", "Keep one visit that is not about care — an hour with no tasks keeps you their child.", "Say out loud what you cannot do — a limit named early is kinder than one hit later."]'::jsonb, 'as needed', array['Caregiving', 'Family']::text[], 1, '2026-10-31T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
